CREATE TABLE IF NOT EXISTS "student_skills" ( skill_id INTEGER PRIMARY KEY AUTOINCREMENT, student_id TEXT NOT NULL, skill_name TEXT NOT NULL, skill_category TEXT CHECK(skill_category IN (  'technical', 'soft_skill', 'language', 'tool', 'domain' )), proficiency_level TEXT CHECK(proficiency_level IN (  'beginner', 'intermediate', 'advanced', 'expert' )), years_experience REAL, is_featured BOOLEAN DEFAULT 0, added_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "acquired_date" TEXT, "verified" BOOLEAN DEFAULT 0, UNIQUE(student_id, skill_name));
